import{Bt as e,It as t,St as n,bt as r,gt as i,nt as a,xt as o,yt as s}from"./chunks/framework.D2FS3J_H.js";var c=JSON.parse(`{"title":"Elements","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"docs/elements.md","filePath":"docs/elements.md"}`),l={name:`docs/elements.md`};function u(a,c,l,u,d,f){let p=e(`EmbeddedHylimoEditor`);return t(),s(`div`,null,[c[0]||=r(`<h1 id="elements" tabindex="-1">Elements <a class="header-anchor" href="#elements" aria-label="Permalink to “Elements”">​</a></h1><p>An element is the basic building block of a diagram. <a href="./diagram.html">The DSL page</a> describes how elements are combined into a diagram; this page documents the elements themselves: their attributes, their styles, and the contents they accept.</p><p>There are sixteen element types, in two groups. Layout elements (<code>container</code>, <code>shape</code>, <code>divider</code>, <code>text</code>, <code>span</code> and <code>path</code>) are boxes: each is measured and then placed by its parent. Canvas elements (<code>canvas</code> and everything placed on one) are positioned by coordinates and connected to each other.</p><h2 id="calling-an-element" tabindex="-1">Calling an element <a class="header-anchor" href="#calling-an-element" aria-label="Permalink to “Calling an element”">​</a></h2><p>Each element is created by a function of the same name. Attributes are passed as named arguments, contents either as a <code>contents</code> list or in a trailing lambda:</p>`,5),n(p,{code:`diagram%20%7B%0A%20%20%20%20element(shape(shape%20%3D%20defaultShapes.rect%2C%20fill%20%3D%20%22%23dbeafe%22)%20%7B%0A%20%20%20%20%20%20%20%20text%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20span(text%20%3D%20%22Hello%20World%22)%0A%20%20%20%20%20%20%20%20%7D%20styles%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20margin%20%3D%2016%0A%20%20%20%20%20%20%20%20%7D%0A%20%20%20%20%7D)%0A%7D%0A`}),c[1]||=r(`<p>Both content forms produce the same element, so <code>text { span(text = &quot;a&quot;) }</code> is equivalent to <code>text(contents = list(span(text = &quot;a&quot;)))</code>.</p><h2 id="attribute-sources" tabindex="-1">Attribute sources <a class="header-anchor" href="#attribute-sources" aria-label="Permalink to “Attribute sources”">​</a></h2><p>An attribute can be set in three ways: as a named argument, in a <code>styles</code> block applied to the element, or in a style rule which matches the element by type or class.</p><div class="language-hyl"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">HyLiMo</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// as an argument</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">span</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(text </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Hello&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, fontWeight </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bold&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// in a styles block on this element</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">span</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(text </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Hello&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">styles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    fontWeight </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bold&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// in a rule matching every span</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">styles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;span&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        fontWeight </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;bold&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Only style attributes can be set by the second and third form. The remaining attributes are structural, such as a shape&#39;s <code>shape</code>, a span&#39;s <code>text</code> or a line point&#39;s <code>lineProvider</code>, and have to be passed as arguments. The tables below list the two kinds separately. See <a href="./diagram.html#styles">Styles</a> for selectors, precedence and style variables.</p><div class="warning custom-block"><p class="custom-block-title">Undeclared attributes are ignored</p><p>Attribute values are type checked, so <code>text(width = &quot;abc&quot;)</code> reports that <code>width</code> must be a number.</p><p>Attribute names are not checked against the element type. <code>text(padding = 10)</code>, and equally a <code>type(&quot;text&quot;) { padding = 10 }</code> rule, is accepted and has no effect, because <code>text</code> does not declare <code>padding</code>. No diagnostic is reported in that case, so the tables below are the reference for which attributes an element supports.</p></div><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><p>The permitted contents of an element are defined by the type of its <code>contents</code> attribute, so invalid nesting is reported as a type error.</p><table tabindex="0"><thead><tr><th>Element</th><th>May contain</th><th>Cardinality</th></tr></thead><tbody><tr><td><code>container</code></td><td><code>canvas</code>, <code>text</code>, <code>shape</code>, <code>path</code>, <code>container</code></td><td>0..*</td></tr><tr><td><code>shape</code></td><td>the same, plus <code>divider</code></td><td>0..*</td></tr><tr><td><code>canvasElement</code></td><td>the same as <code>container</code></td><td>0..*</td></tr><tr><td><code>marker</code></td><td>the same as <code>container</code></td><td>0..*</td></tr><tr><td><code>text</code></td><td><code>span</code></td><td>0..*</td></tr><tr><td><code>canvas</code></td><td><code>canvasElement</code>, <code>canvasConnection</code>, <code>absolutePoint</code>, <code>relativePoint</code>, <code>linePoint</code></td><td>0..*</td></tr><tr><td><code>canvasConnection</code></td><td><code>canvasLineSegment</code>, <code>canvasBezierSegment</code>, <code>canvasAxisAlignedSegment</code>, <code>marker</code></td><td>1..*</td></tr><tr><td><code>span</code>, <code>divider</code>, <code>path</code>, segments, points</td><td>nothing</td><td>0</td></tr></tbody></table><p>Two entries of this table have further consequences:</p><ul><li>A <code>divider</code> is valid only as a direct child of a <code>shape</code>. No other content type includes it, <code>container</code> in particular does not, so no additional check is required.</li><li>A <code>canvas</code> is a regular content element and can be placed wherever a <code>shape</code> or a <code>container</code> can. Nested canvases are the basis for UML packages and swimlanes.</li></ul><h2 id="style-attribute-groups" tabindex="-1">Style attribute groups <a class="header-anchor" href="#style-attribute-groups" aria-label="Permalink to “Style attribute groups”">​</a></h2><p>The following groups of style attributes are shared between elements, and are referred to by name in the element sections below.</p><p><strong>Size</strong>: <code>width</code>, <code>height</code>, <code>minWidth</code>, <code>minHeight</code>, <code>maxWidth</code>, <code>maxHeight</code>. <code>width</code> and <code>height</code> take precedence over the corresponding minimum and maximum.</p><p><strong>Alignment</strong>: <code>hAlign</code> (<code>&quot;left&quot;</code>, <code>&quot;right&quot;</code>, <code>&quot;center&quot;</code>) and <code>vAlign</code> (<code>&quot;top&quot;</code>, <code>&quot;bottom&quot;</code>, <code>&quot;center&quot;</code>) position the element within the space assigned to it by its parent. The <code>HAlign</code> and <code>VAlign</code> enum objects provide the values, so <code>HAlign.Center</code> can be used instead of <code>&quot;center&quot;</code>.</p><p><strong>Margin</strong>: <code>margin</code>, <code>marginTop</code>, <code>marginRight</code>, <code>marginBottom</code>, <code>marginLeft</code>. A margin is space around the element which its siblings have to accommodate.</p><p><strong>Flex</strong>: <code>base</code>, <code>grow</code> and <code>shrink</code> control how the element takes up the remaining space along the primary axis of an <code>hbox</code> or <code>vbox</code>, analogous to the flexbox properties of the same name.</p><p><strong>Visibility</strong>: <code>visibility</code> is <code>&quot;visible&quot;</code>, <code>&quot;hidden&quot;</code> (not rendered, space retained) or <code>&quot;collapse&quot;</code> (not rendered, no space). The <code>Visibility</code> enum object provides the values.</p><p><strong>Contents</strong>: <code>layout</code> is <code>&quot;stack&quot;</code> (the default, children on the z-axis), <code>&quot;vbox&quot;</code> or <code>&quot;hbox&quot;</code>. <code>padding</code> is space between the element and its contents. In contrast to a margin, padding belongs to the element itself: the element grows by it and its contents are inset by it.</p><p><strong>Stroke</strong>: <code>stroke</code> (a color), <code>strokeOpacity</code>, <code>strokeWidth</code>, <code>strokeDash</code> and <code>strokeDashSpace</code> for dashed strokes, and <code>strokeLineJoin</code>, <code>strokeLineCap</code> and <code>strokeMiterLimit</code> for how corners and ends are drawn. No stroke is drawn unless <code>stroke</code> is set.</p><p><strong>Fill</strong>: <code>fill</code> (a color) and <code>fillOpacity</code>. For elements which are meant to hide what is behind them, use the <code>background</code> style variable instead of a fixed color, so that they render correctly in both themes.</p><p>Support by element:</p><table tabindex="0"><thead><tr><th>Element</th><th>Size</th><th>Align</th><th>Margin</th><th>Flex</th><th>Visibility</th><th>Contents</th><th>Stroke</th><th>Fill</th></tr></thead><tbody><tr><td><code>container</code></td><td>yes</td><td>yes</td><td>yes</td><td>yes</td><td>yes</td><td>yes</td><td>no</td><td>no</td></tr><tr><td><code>shape</code></td><td>yes</td><td>yes</td><td>yes</td><td>yes</td><td>yes</td><td>yes</td><td>yes</td><td>yes</td></tr><tr><td><code>divider</code></td><td>no</td><td>no</td><td>yes</td><td>no</td><td>yes</td><td>no</td><td>partly</td><td>no</td></tr><tr><td><code>text</code></td><td>yes</td><td>yes</td><td>yes</td><td>yes</td><td>yes</td><td>no</td><td>no</td><td>no</td></tr><tr><td><code>span</code></td><td>no</td><td>no</td><td>no</td><td>no</td><td>no</td><td>no</td><td>no</td><td>yes</td></tr><tr><td><code>path</code></td><td>yes</td><td>yes</td><td>yes</td><td>yes</td><td>yes</td><td>no</td><td>yes</td><td>yes</td></tr><tr><td><code>canvas</code></td><td>yes</td><td>yes</td><td>yes</td><td>yes</td><td>yes</td><td>no</td><td>no</td><td>no</td></tr><tr><td><code>canvasElement</code></td><td>yes</td><td>yes</td><td>no</td><td>no</td><td>yes</td><td>yes</td><td>no</td><td>no</td></tr><tr><td><code>canvasConnection</code></td><td>no</td><td>no</td><td>no</td><td>no</td><td>no</td><td>no</td><td>yes</td><td>no</td></tr><tr><td><code>marker</code></td><td>yes</td><td>yes</td><td>yes</td><td>yes</td><td>yes</td><td>yes</td><td>no</td><td>no</td></tr><tr><td>the segments and points</td><td>no</td><td>no</td><td>no</td><td>no</td><td>no</td><td>no</td><td>no</td><td>no</td></tr></tbody></table><p>The <code>divider</code> entry is partial: it supports <code>stroke</code>, <code>strokeOpacity</code>, <code>strokeWidth</code>, <code>strokeDash</code> and <code>strokeDashSpace</code>, but not <code>strokeLineJoin</code>, <code>strokeLineCap</code> or <code>strokeMiterLimit</code>, see <a href="#divider">below</a>.</p><p><code>class</code> is supported by every element. It is not a style attribute, but the attribute style rules select on.</p><h2 id="layout-elements" tabindex="-1">Layout elements <a class="header-anchor" href="#layout-elements" aria-label="Permalink to “Layout elements”">​</a></h2><h3 id="container" tabindex="-1"><code>container</code> <a class="header-anchor" href="#container" aria-label="Permalink to “container”">​</a></h3><p>A box which lays out its children and has no appearance of its own.</p>`,28),n(p,{code:`diagram%20%7B%0A%20%20%20%20element(container(layout%20%3D%20%22hbox%22)%20%7B%0A%20%20%20%20%20%20%20%20text%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20span(text%20%3D%20%22left%22)%0A%20%20%20%20%20%20%20%20%7D%20styles%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20marginRight%20%3D%2020%0A%20%20%20%20%20%20%20%20%7D%0A%20%20%20%20%20%20%20%20text%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20span(text%20%3D%20%22right%22)%0A%20%20%20%20%20%20%20%20%7D%0A%20%20%20%20%7D)%0A%7D%0A`}),c[2]||=r(`<p>Styles: Size, Align, Margin, Flex, Visibility, Contents.</p><h3 id="shape" tabindex="-1"><code>shape</code> <a class="header-anchor" href="#shape" aria-label="Permalink to “shape”">​</a></h3><p>A parametric graphic, such as a rectangle, ellipse, diamond or database, whose outline is fitted to its content or its content to the outline. See <a href="./shapes.html">Shapes</a>.</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Meaning</th></tr></thead><tbody><tr><td><code>shape</code></td><td>the shape definition: an object with a <code>path</code> and an optional <code>decoration</code></td></tr></tbody></table><table tabindex="0"><thead><tr><th>Style</th><th>Meaning</th></tr></thead><tbody><tr><td><code>cornerRounding</code></td><td>the corner rounding radius, usable as <code>r</code> in the shape path</td></tr></tbody></table><p>Styles: <code>cornerRounding</code>, Size, Align, Margin, Flex, Visibility, Contents, Stroke, Fill.</p><h3 id="divider" tabindex="-1"><code>divider</code> <a class="header-anchor" href="#divider" aria-label="Permalink to “divider”">​</a></h3><p>A rule drawn across the interior of a <code>shape</code>, terminating exactly at its border and at every decoration in its way. It has no attributes of its own: the shape it belongs to, its orientation and its extent all follow from its position in the tree. See <a href="./shapes.html#dividers">Dividers</a>.</p><p>Styles: Margin, Visibility, and <code>stroke</code>, <code>strokeOpacity</code>, <code>strokeWidth</code>, <code>strokeDash</code> and <code>strokeDashSpace</code>. <code>strokeLineJoin</code>, <code>strokeLineCap</code> and <code>strokeMiterLimit</code> are not supported, as a divider is a straight line which ends where the border of the shape does. It has no size, alignment or flex attributes either: it spans the space the shape leaves it, and never increases the size of the shape.</p><h3 id="text" tabindex="-1"><code>text</code> <a class="header-anchor" href="#text" aria-label="Permalink to “text”">​</a></h3><p>A block of text consisting of one or more <code>span</code>s. Each span carries its own font styling, which allows mixed formatting within one text:</p>`,11),n(p,{code:`diagram%20%7B%0A%20%20%20%20element(text%20%7B%0A%20%20%20%20%20%20%20%20span(text%20%3D%20%22normal%20%22)%0A%20%20%20%20%20%20%20%20span(text%20%3D%20%22bold%22%2C%20fontWeight%20%3D%20%22bold%22)%0A%20%20%20%20%20%20%20%20span(text%20%3D%20%22%20and%20%22)%0A%20%20%20%20%20%20%20%20span(text%20%3D%20%22italic%22%2C%20fontStyle%20%3D%20%22italic%22)%0A%20%20%20%20%7D)%0A%7D%0A`}),c[3]||=r(`<table tabindex="0"><thead><tr><th>Style</th><th>Meaning</th></tr></thead><tbody><tr><td><code>direction</code></td><td><code>&quot;horizontal&quot;</code> (the default), <code>&quot;clockwise&quot;</code> (reading top to bottom) or <code>&quot;counterclockwise&quot;</code></td></tr></tbody></table><p><code>direction</code> rotates the text by a quarter turn. Reading order is preserved and the measurements are transposed: a turned text reports its line height as width and its line length as height. A vertical swimlane header in a horizontal row is placed this way, without any change to the surrounding layout.</p>`,2),n(p,{code:`diagram%20%7B%0A%20%20%20%20element(container(layout%20%3D%20%22hbox%22)%20%7B%0A%20%20%20%20%20%20%20%20text%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20span(text%20%3D%20%22horizontal%22)%0A%20%20%20%20%20%20%20%20%7D%20styles%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20marginRight%20%3D%2030%0A%20%20%20%20%20%20%20%20%7D%0A%20%20%20%20%20%20%20%20text(direction%20%3D%20%22clockwise%22)%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20span(text%20%3D%20%22clockwise%22)%0A%20%20%20%20%20%20%20%20%7D%20styles%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20marginRight%20%3D%2030%0A%20%20%20%20%20%20%20%20%7D%0A%20%20%20%20%20%20%20%20text(direction%20%3D%20%22counterclockwise%22)%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20span(text%20%3D%20%22counterclockwise%22)%0A%20%20%20%20%20%20%20%20%7D%0A%20%20%20%20%7D)%0A%7D%0A`}),c[4]||=r(`<p>Styles: <code>direction</code>, Size, Align, Margin, Flex, Visibility. A text has neither fill nor stroke; the color is set on its spans.</p><h3 id="span" tabindex="-1"><code>span</code> <a class="header-anchor" href="#span" aria-label="Permalink to “span”">​</a></h3><p>A run of text with its own font styling. It is the only element which carries font attributes.</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Meaning</th></tr></thead><tbody><tr><td><code>text</code></td><td>the text to display</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Style</th><th>Meaning</th></tr></thead><tbody><tr><td><code>fontFamily</code>, <code>fontSize</code>, <code>fontWeight</code>, <code>fontStyle</code>, <code>fontFeatureSettings</code></td><td>which font is used and how</td></tr><tr><td><code>underline</code>, <code>underlineOpacity</code>, <code>underlineWidth</code>, <code>underlineDash</code>, <code>underlineDashSpace</code></td><td>an underline and its appearance</td></tr><tr><td><code>strikethrough</code>, <code>strikethroughOpacity</code>, <code>strikethroughWidth</code>, <code>strikethroughDash</code>, <code>strikethroughDashSpace</code></td><td>a strikethrough and its appearance</td></tr></tbody></table><p><code>fontWeight</code> is <code>&quot;normal&quot;</code> or <code>&quot;bold&quot;</code>, <code>fontStyle</code> is <code>&quot;normal&quot;</code> or <code>&quot;italic&quot;</code>, and <code>fontFamily</code> must name one of the diagram&#39;s <a href="./diagram.html#fonts">registered families</a>. <code>underline</code> and <code>strikethrough</code> take a color, or <code>true</code> to use the fill color.</p><p>Styles: the above and Fill, which is the color of the text. A span has no size, margin or alignment of its own; it is laid out within its <code>text</code>.</p><h3 id="path" tabindex="-1"><code>path</code> <a class="header-anchor" href="#path" aria-label="Permalink to “path”">​</a></h3><p>An SVG path, scaled into the space assigned to the element.</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Meaning</th></tr></thead><tbody><tr><td><code>path</code></td><td>the SVG path string</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Style</th><th>Meaning</th></tr></thead><tbody><tr><td><code>stretch</code></td><td><code>&quot;fill&quot;</code> (the default) scales each axis independently, <code>&quot;uniform&quot;</code> keeps the aspect ratio</td></tr></tbody></table>`,11),n(p,{code:`diagram%20%7B%0A%20%20%20%20element(container(layout%20%3D%20%22hbox%22)%20%7B%0A%20%20%20%20%20%20%20%20path(path%20%3D%20%22M%200%200%20L%201%201%20L%202%200%22%2C%20stretch%20%3D%20%22fill%22%2C%20class%20%3D%20list(%22mark%22))%20styles%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20marginRight%20%3D%2030%0A%20%20%20%20%20%20%20%20%7D%0A%20%20%20%20%20%20%20%20path(path%20%3D%20%22M%200%200%20L%201%201%20L%202%200%22%2C%20stretch%20%3D%20%22uniform%22%2C%20class%20%3D%20list(%22mark%22))%0A%20%20%20%20%7D)%0A%20%20%20%20styles%20%7B%0A%20%20%20%20%20%20%20%20cls(%22mark%22)%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20width%20%3D%20160%0A%20%20%20%20%20%20%20%20%20%20%20%20height%20%3D%2050%0A%20%20%20%20%20%20%20%20%20%20%20%20stroke%20%3D%20%22%23e2574c%22%0A%20%20%20%20%20%20%20%20%20%20%20%20strokeWidth%20%3D%203%0A%20%20%20%20%20%20%20%20%7D%0A%20%20%20%20%7D%0A%7D%0A`}),c[5]||=r(`<p>Styles: <code>stretch</code>, Size, Align, Margin, Flex, Visibility, Stroke, Fill.</p><p>A path is not fitted to content and cannot contain any. For a graphic which holds content and grows with it, use a <a href="./shapes.html#custom-shapes">custom shape</a> instead.</p><h2 id="canvas-elements" tabindex="-1">Canvas elements <a class="header-anchor" href="#canvas-elements" aria-label="Permalink to “Canvas elements”">​</a></h2><p>A canvas positions its contents by coordinates instead of laying them out, and connects them. The <a href="./diagram.html#canvas-constructs">canvas constructs</a> <code>element</code>, <code>apos</code>, <code>rpos</code>, <code>lpos</code>, <code>layout</code> and <code>with</code> are the usual way to create the elements documented in this section.</p><h3 id="canvas" tabindex="-1"><code>canvas</code> <a class="header-anchor" href="#canvas" aria-label="Permalink to “canvas”">​</a></h3><p>The element which holds positioned content. The body of every <code>diagram</code> is a canvas, and since a canvas is a regular content element, canvases can be nested.</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Meaning</th></tr></thead><tbody><tr><td><code>syncWith</code></td><td>join the coordinate group anchored at another canvas: <code>[canvas = &lt;a canvas&gt;, x = true, y = true]</code></td></tr></tbody></table><p>By default a canvas reports exactly the bounds of its contents, so two sibling canvases with different content have different sizes and unrelated origins. <code>syncWith</code> overrides this along the selected axes: every member of a group adopts the origin and extent of the group there, so the coordinate systems of the members align and their sizes agree. Swimlanes are built on this, and use it to share the flow axis between all lanes.</p><p>The referenced canvas has to be an ancestor of the canvas which declares <code>syncWith</code>; any other reference is reported as an error. A canvas measures all of its contents before laying any of them out, and that ordering is what allows a group to be resolved in two passes. Only an ancestor guarantees it.</p><p>Group membership is declared by the member, and is not derived from nesting. A canvas nested inside a group member, such as a package drawn inside a swimlane, therefore keeps its own size.</p><p>Styles: Size, Align, Margin, Flex, Visibility.</p><h3 id="canvaselement" tabindex="-1"><code>canvasElement</code> <a class="header-anchor" href="#canvaselement" aria-label="Permalink to “canvasElement”">​</a></h3><p>Content positioned on a canvas, created by <code>element { … } layout { … }</code>.</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Meaning</th></tr></thead><tbody><tr><td><code>pos</code></td><td>the position: a point element, or <code>null</code></td></tr></tbody></table><table tabindex="0"><thead><tr><th>Style</th><th>Meaning</th></tr></thead><tbody><tr><td><code>rotation</code></td><td>the rotation in degrees</td></tr></tbody></table><p>Styles: <code>rotation</code>, Size, Align, Visibility, Contents. Margin and flex attributes are not supported, as a canvas positions the element by coordinates rather than relative to siblings.</p><details class="details custom-block"><summary><code>source</code> and <code>editExpression</code></summary><p>Both are set by the DSL and hold the metadata the graphical editor requires to write a change back into the source. They are not intended to be set manually.</p></details><h3 id="canvasconnection" tabindex="-1"><code>canvasConnection</code> <a class="header-anchor" href="#canvasconnection" aria-label="Permalink to “canvasConnection”">​</a></h3><p>A connection between two points, consisting of one or more segments. See <a href="./diagram.html#with-operator">the <code>with</code> operator</a> for how one is usually built.</p><table tabindex="0"><thead><tr><th>Attribute</th><th>Meaning</th></tr></thead><tbody><tr><td><code>start</code></td><td>the point the connection starts at</td></tr><tr><td><code>startMarker</code></td><td>the marker at the start, if any</td></tr><tr><td><code>endMarker</code></td><td>the marker at the end, if any</td></tr></tbody></table><p>The contents are the segments of the connection, of which there is at least one. Segments are chained: each segment defines only its <code>end</code>, its start being the end of the preceding segment, or <code>start</code> in case of the first segment.</p><p>Styles: Stroke.</p><h3 id="the-segments" tabindex="-1">The segments <a class="header-anchor" href="#the-segments" aria-label="Permalink to “The segments”">​</a></h3><table tabindex="0"><thead><tr><th>Element</th><th>Attributes</th><th>Meaning</th></tr></thead><tbody><tr><td><code>canvasLineSegment</code></td><td><code>end</code></td><td>a straight line</td></tr><tr><td><code>canvasBezierSegment</code></td><td><code>end</code>, <code>startControlPoint</code>, <code>endControlPoint</code></td><td>a cubic bezier curve</td></tr><tr><td><code>canvasAxisAlignedSegment</code></td><td><code>end</code>, <code>verticalPos</code></td><td>an axis-aligned poly line of one to three parts</td></tr></tbody></table><p><code>verticalPos</code> is clamped to the range -1 to 1. A positive value is the relative position of the vertical part of the segment, a negative value the relative position of the horizontal part. The sign therefore selects whether the segment runs horizontally or vertically first.</p><p>Segments have no styles of their own; a connection is styled as a whole.</p><h3 id="the-points" tabindex="-1">The points <a class="header-anchor" href="#the-points" aria-label="Permalink to “The points”">​</a></h3><p>A point has no size and is never rendered. <code>apos</code>, <code>rpos</code> and <code>lpos</code> create the three kinds.</p><table tabindex="0"><thead><tr><th>Element</th><th>Attributes</th><th>Styles</th></tr></thead><tbody><tr><td><code>absolutePoint</code></td><td>none</td><td><code>x</code>, <code>y</code></td></tr><tr><td><code>relativePoint</code></td><td><code>targetX</code>, <code>targetY</code></td><td><code>offsetX</code>, <code>offsetY</code></td></tr><tr><td><code>linePoint</code></td><td><code>lineProvider</code></td><td><code>pos</code>, <code>distance</code></td></tr></tbody></table><p>The coordinates are declared as style attributes, so a point can be moved by a style rule or a class like any other styled property, and the graphical editor writes a moved point back the same way it writes a color.</p><p>A <code>relativePoint</code> references its target separately per axis. <code>targetX</code> and <code>targetY</code> are usually the same element, which is what <code>rpos</code> produces, but may also be two different ones, in which case the point follows one element horizontally and another vertically. Both offsets default to 0.</p><p>A <code>linePoint</code> is positioned on the outline of a <code>canvasElement</code> or along a <code>canvasConnection</code>. <code>pos</code> is the relative position on that line, between 0 and 1; the <code>Position</code> enum object provides the eight compass positions of an outline, so <code>Position.TopRight</code> can be used instead of <code>0.875</code>. <code>pos</code> also accepts a pair of <code>(segment, position within that segment)</code>, which addresses a specific segment of a multi-segment connection. <code>distance</code> offsets the point perpendicular to the line and defaults to 0.</p><p>The line provider has to be part of the same canvas as the point, or of a canvas nested inside it.</p><h3 id="marker" tabindex="-1"><code>marker</code> <a class="header-anchor" href="#marker" aria-label="Permalink to “marker”">​</a></h3><p>Content placed at the start or end of a connection, such as an arrow head, a diamond or a cross.</p><table tabindex="0"><thead><tr><th>Style</th><th>Meaning</th><th>Default</th></tr></thead><tbody><tr><td><code>refX</code></td><td>the x coordinate of the reference point, as a fraction of the marker width</td><td>1</td></tr><tr><td><code>refY</code></td><td>the y coordinate of the reference point, as a fraction of the marker height</td><td>0.5</td></tr><tr><td><code>lineStart</code></td><td>the relative (0..1) offset within the marker at which the line starts</td><td>0</td></tr></tbody></table><p>The reference point is placed at the endpoint of the connection. <code>lineStart</code> defines where the stroke of the connection ends within the marker: 0 for a closed marker the line must not enter, such as a filled triangle, and 1 for an open marker the line runs through to the tip, such as an arrow head.</p>`,37),n(p,{code:`diagram%20%7B%0A%20%20%20%20a%20%3D%20element%20%7B%0A%20%20%20%20%20%20%20%20text%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20span(text%20%3D%20%22A%22)%0A%20%20%20%20%20%20%20%20%7D%0A%20%20%20%20%7D%0A%20%20%20%20b%20%3D%20element%20%7B%0A%20%20%20%20%20%20%20%20text%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20span(text%20%3D%20%22B%22)%0A%20%20%20%20%20%20%20%20%7D%0A%20%20%20%20%7D%20layout%20%7B%0A%20%20%20%20%20%20%20%20pos%20%3D%20apos(260%2C%200)%0A%20%20%20%20%7D%0A%0A%20%20%20%20--%20%3D%20internal.createConnectionOperator(%0A%20%20%20%20%20%20%20%20endMarkerFactory%20%3D%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20marker(contents%20%3D%20list(%0A%20%20%20%20%20%20%20%20%20%20%20%20%20%20%20%20path(path%20%3D%20%22M%200%200%20L%2010%206%20L%200%2012%20Z%22%2C%20class%20%3D%20list(%22tip%22))%0A%20%20%20%20%20%20%20%20%20%20%20%20))%0A%20%20%20%20%20%20%20%20%7D%0A%20%20%20%20)%0A%0A%20%20%20%20a%20--%20b%20with%20%7B%0A%20%20%20%20%20%20%20%20over%20%3D%20start(Position.Right).line(end(Position.Left))%0A%20%20%20%20%7D%0A%0A%20%20%20%20styles%20%7B%0A%20%20%20%20%20%20%20%20cls(%22tip%22)%20%7B%0A%20%20%20%20%20%20%20%20%20%20%20%20width%20%3D%2020%0A%20%20%20%20%20%20%20%20%20%20%20%20height%20%3D%2020%0A%20%20%20%20%20%20%20%20%20%20%20%20fill%20%3D%20var(%22primary%22)%0A%20%20%20%20%20%20%20%20%7D%0A%20%20%20%20%7D%0A%7D%0A`}),c[6]||=i(`p`,null,[o(`Styles: `),i(`code`,null,`refX`),o(`, `),i(`code`,null,`refY`),o(`, `),i(`code`,null,`lineStart`),o(`, Size, Align, Margin, Flex, Visibility, Contents.`)],-1)])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};